"""Build report-template.html for the Off-plan OR Post-handover report from its base template, adding the
optional modules (all switched on by the data file, so a plain report looks exactly like before):
  - Distressed deal test vs the SAME PROJECT  (data: distressed:true + proj:{...})  -> objectives, Market evidence, Similar listings, distressed top card
  - Mortgage at handover / developer x bank offer (data: construction, mortgage, eibor, buyers, varDefaults, offer?) -> off-plan only
Usage:  python3 make_template.py            (off-plan)
        python3 make_template.py posthandover
Edit base-template.html (the plain report) for layout fixes, then run this again."""
import pathlib, sys
here = pathlib.Path(__file__).parent
def sib(local, kit):
    """a sibling report's file: Calculators layout (local) or skill-repo layout (kit)"""
    return here / local if (here / local).parent.exists() else here / kit
VARIANT = sys.argv[1] if len(sys.argv) > 1 else "offplan"
CFG = {"offplan": dict(base=here / "base-template.html", out=here / "report-template.html", mort=True),
       "posthandover": dict(base=sib("../../Post-Handover Reports/template/base-template.html", "../../../posthandover-report/kit/template/base-template.html"),
                            out=sib("../../Post-Handover Reports/template/report-template.html", "../../../posthandover-report/kit/template/report-template.html"), mort=False)}[VARIANT]
s = CFG["base"].read_text()

def sub(a, b, n=1):
    global s
    assert s.count(a) == n, (a[:120], s.count(a))
    s = s.replace(a, b)

