NAME = {"offplan": ("Off-plan", "Off-plan evaluation", "Distressed off-plan evaluation", "v1.3.1", "v1.4.0", "v1.3 ©", "v1.4 ©"),
        "posthandover": ("Post-Handover", "Post-handover evaluation", "Distressed post-handover evaluation", "v1.1.1", "v1.2.0", "v1.1 ©", "v1.2 ©")}[VARIANT]
