sub(NAME[0] + " Report " + NAME[5], NAME[0] + " Report " + NAME[6])
sub('$("#eyebrow").textContent=(AGENT.name?AGENT.name+" · ":"")+"' + NAME[1] + '";',
    '$("#eyebrow").textContent=(AGENT.name?AGENT.name+" · ":"")+(D.distressed&&D.proj?"' + NAME[2] + '":"' + NAME[1] + '");')
