sub('["Admin fee",aed(D.oqood)]', '[D.adminLabel||"Admin fee",aed(D.oqood)]')
sub('${L("Admin fee","",aed(D.oqood))}', '${L(D.adminLabel||"Admin fee",D.adminHow||"",aed(D.oqood))}')
